TLM.f("Sancti/10-24",{"officium":"S. Raphælis Archangeli","rule":["ex Sancti/05-08","Gloria","CredoDA"],"ruleInherited":["Gloria","CredoDA"],"fallback":"Sancti/05-08","sections":{"Introitus":[{"k":"ref","la":"Ps 102:20"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Bénedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."}],"Oratio":[{"k":"text","la":"Deus, qui beátum Raphaélem Archángelum Tobíæ fámulo tuo cómitem dedísti in via: concéde nobis fámulis tuis; ut ejúsdem semper protegámur custódia et muniámur auxílio."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Tobíæ"},{"k":"ref","la":"Tob 12:7-15"},{"k":"text","la":"In diébus illis: Dixit Angelus Ráphaël ad Tobíam: Sacraméntum regis abscóndere bonum est: ópera autem Dei reveláre et confitéri honoríficum est. Bona est orátio cum jejúnio, et eleemósyna magis quam thesáuros auri recóndere: quóniam eleemósyna a morte liberat, et ipsa est, quæ purgat peccáta et facit invenire misericórdiam et vitam ætérnam. Qui autem faciunt peccátum et iniquitátem, hostes sunt ánimæ suæ. Manifésto ergo vobis veritátem, et non abscóndam a vobis occúltum sermónem. Quando orábas cum lácrimis, et sepeliébas mórtuos, et derelinquébas prándium tuum, et mórtuos abscondébas per diem in domo tua, et nocte sepeliébas eos, ego óbtuli oratiónem tuam Dómino. Et quia accéptus eras Deo, necésse fuit, ut tentátio probáret te. Et nunc misit me Dóminus, ut curárem te, et Saram uxórem fílii tui a dæmónio liberárem. Ego enim sum Raphaël Angelus, unus ex septem, qui astámus ante Dóminum."}],"Graduale":[{"k":"ref","la":"Tob 8:3"},{"k":"text","la":"Angelus Dómini Raphaël apprehéndit et ligávit dæmonem."},{"k":"ref","la":"Ps 146:5"},{"k":"text","la":"Magnus Dóminus noster, et magna virtus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 137:1-2"},{"k":"text","la":"In conspéctu Angelórum psallam tibi: adorábo ad templum sanctum tuum, et confitébor nómini tuo, Dómine. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Benedic, ánima mea, Dóminum: et ómnia interióra mea nomen sanctum ejus. Allelúja."},{"k":"ref","la":"Tob 3:25; 5:11"},{"k":"text","la":"Missus est Angelus Dómini sanctus Ráphaël a Deo ad Tobiam, et salutávit eum, et dixit: Gáudium sit tibi semper. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 148:2"},{"k":"text","la":"Laudáte Dóminum, omnes Angeli ejus: laudáte eum, omnes virtútes ejus."},{"k":"ref","la":"Ps 102:21"},{"k":"text","la":"Benedícite Dóminum, omnes virtútes ejus: minístri ejus, qui fácitis voluntátem ejus."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 5:1-4"},{"k":"text","la":"In illo témpore: Erat dies festus Judæórum, et ascéndit Jesus Jerosólymam. Est autem Jerosólymis Probática piscína, quæ cognominátur hebráice Bethsaida, quinque pórticus habens. In his jacébat multitúdo magna languéntium, cæcórum, claudórum, aridórum exspectántium aquæ motum. Angelus autem Dómini descendébat secúndum tempus in piscínam, et movebátur aqua. Et, qui prior descendísset in piscínam post motiónem aquæ, sanus fiebat, a quacúmque detinebátur infirmitáte."}],"Offertorium":[{"k":"ref","la":"Apoc 8:3; 8:4"},{"k":"text","la":"Stetit Angelus juxta aram templi, habens thuríbulum áureum in manu sua, et data sunt ei incénsa multa: et ascéndit fumus aromátum in conspéctu Dei."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, laudis offérimus, supplíciter deprecántes: ut eásdem, angélico pro nobis interveniénte suffrágio, et placátus accípias, et ad salútem nostram proveníre concédas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Dan 3:58"},{"k":"text","la":"Benedícite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula."}],"Postcommunio":[{"k":"text","la":"Dirigere dignáre, Dómine Deus, in adjutórium nostrum sanctum Raphaélem Archángelum: et, quem tuæ majestáti semper assístere crédimus, tibi nostras exíguas preces benedicéndas assígnet."},{"k":"macro","name":"Per Dominum"}]},"hr":{"92504dc00afe8cf8":{"t":"Ps 102, 20, Ps 102, 1\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih. (Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina, i sve što je u meni njegovo sveto ime.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih.","kn":"(Ps. 102, 20), Blagosivajte Goispodlna svi anđeli njegovi, koji ste silni krepošću i izvršujete riječ njegovu slušajući glas besjeda njegovih. (Ps. 102, 1) Blagosivaj, dušo moja. Gospodina., i sve što je u meni, sveto ime njegovo. Slava Ocu . . . Blagosivajte . .","knRef":"Kniewald 1942, str. 530–531 (snimka 266) (OCR)"},"ec6a98f7294d79f9":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženoga Rafaela arkanđela dao slugi svojemu Tobiji za pratioca na putu, daj nama svojim slugama da nas on uvijek štiti kao čuvar i brani svojom pomoću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si Tobiji, sluzi svomu, na njegovu putu, dodijelio blaženog arkanđela Rafaela kao druga, dopusti nama, službenicima svojim, da nas uvijek štiti njegova prisutnost i brani njegova pomoć, po G. II.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"99a494615533ccbe":{"t":"Tob 12, 7-15\nČitanje knjige Tobije. U one dane Rafael reče Tobiji: Uistinu je dobro sakrivati vladarevu tajnu, ali je pohvalno otkriti i objaviti Božja djela. Dobra je molitva i post i bolje je dijeliti milostinju nego skupljati zalihe zlata. Milostinja oslobađa od smrti, čisti od grijeha i čini da se nađe milosrđe i vječni život. Neprijatelji su samih sebe, koji griješe i čine nepravdu. Objavljujemo vam, dakle, istinu i neću vam kriti tajne. Kada si u suzama molio i pokopao mrtve, ostavljao svoje jelo, po danu sakrivao mrtve u svojoj kući, da ih po noći sahraniš, ja sam tvoje molitve prinosio Bogu. Kako si bio Bogu mio, trebalo je da te iskuša ova nevolja. A sada je Gospodin poslao mene, da tebe ozdravim, da Saru ženu tvojega sina oslobodim od zloduha. Ja sam anđeo Rafael, jedan od sedmorice koji stojimo pred Gospodinom.","kn":"Čitanje knjige Tobijine (12. 7-15). U one dane reče Rafael Tobiji: Zaista je dobro sakrivati kraljevu taj,nu, ali je pohvalno otkriti i objaviti Božja djela. Molitva združena s postom je dobra i bo j je dijeliti milostinju, nego skupljati znatno blago. Jer milostinja oslobađa od smrti, ona čisti od gri- jeha i čini, da se nađe milesrđe i vječni život. Sami su svoji neprijatelji oni, koji griješe i čine nepravdu. Objavljujem vam, dakle, istinu i ne ću vam kriti tajne. Kad si sa suzama molio i pokapao mrtve, ostavljao svoje jelo i mrtve u svojoj kući sakrivao po danu, da ih sahraniš po noći, ja sam tvoje molitve prikazao Bogu. Jer si bio Bogu mio, trebalo je da te kuša ova teškoća. I sada je Gospodin poslao mene, da tebe ozdravim, a Saru, ženu tvoga sina, oslotooidim od sotone. Ja sam anđeo Rafael, jedan od sedmorice, koji stojirrio pred Gospodinom. I","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"d70e9b052656a4e4":{"t":"Tob 8, 3, Ps 146, 5\n(Tob 8, 3) Anđeo Gospodnji Rafael uhvatio je i svezao zloduha. (Ps 146, 5) Velik je Gospodin naš i velika je moć njegova.\n\nPs 137, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nPjevam ti pred licem anđela, klanjam se u svetom hramu tvojemu i slavim ime tvoje, Gospodine. <i>Aleluja</i>.","kn":"(Tob. 8, 3). Anđeo Go^odnji Rafael prihvati 1 sveza zloga duha. Velik je Gospodin Bog naš i velika je krepost njegova!\n\nAleluja, aleluja. (Ps. 137, 2). Pred anđelima pjevam Tebi, Gospodine, klanjam se pred svetim hramom Tvojim i hvalim ime Tvoje, aleluja.","knRef":"Kniewald 1942, str. 746–747 (snimka 374) (OCR)"},"40569f731bfdef35":{"t":"Iv 5, 1-4\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bio je židovski blagdan i Isus se uputi u Jeruzalem. U Jeruzalemu je kod Ovčjih vrata ribnjak s pet trijemova koji se hebrejski zove Betsaida. U njima je ležalo vrlo mnogo bolesnika slijepih, hromih, sušičavih koji su očekivali da se uzgiba voda. Anđeo je naime Gospodnji silazio od vremena do vremena u ribnjak i uzgibao vodu. I onaj koji bi prvi sišao u vodu kad se uzgibala, ozdravio bi, pa bolovao on od bilo koje bolesti.","kn":"t Slijedi sveto evanđelje po Ivanu (5, 1-5). U ono vrijeme bio je židovski blagdan i pođe Isus u Jeruzalem. A u Je;ruzalemu je Ovčji ribnjak, koji se hebrejski zove Betsaida, i ima pet trijemova. U njima je ležalo vrlo mnogo slijepih, hromih, sušičavih bolesnika, koji su očekivali, da se uzgiba voda. Jer je od vremena na vrijeme silazio u kupku anđeo Gospodnji i gibala se voda. I koji bi prvi sišao u kupku, kad se voda uzgibala, ozdravio bi, ma da je trpio od bilo koje bolesti.","knRef":"Kniewald 1942, str. 746–747 (snimka 374) (OCR)"},"a4caf3ee133a37bd":{"t":"Otk 8, 3 i 4\nStade anđeo uz žrtvenik hrama držeći zlatnu kadionicu u svojoj ruci, i dadoše mu mnogo tamjana, i uziđe dim od mirisa pred lice Božje.","kn":"(Otkr. 8). Stade anđeo uz žrtvenik hrama, držeći zlatnu kadionicu u ruci svojoj, i dadoše mu mnogo kadila i uziđe dim od mirisa pred lice Božje. Aleluja.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"4dafcf4bb2236e02":{"t":"Prikazujemo ti, Gospodine, žrtve hvale smjerno moleći, da ih na zagovor anđela i milostivo primiš i podaš da nam budu korisne za naše spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, žrtve hvale, smjerno se moleći, da ih anđeoskim zagovorom umilostivl j en primiš i podaš, da nam uspiju za naše spasenje. Po .G. n.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"ff2ac9578506d884":{"t":"Dn 3, 58\nBlagoslivljajte Gospodina, svi anđeli Gospodnji, pjevajte pjesmu i uzvisujte ga u vijeke.","kn":"(Dan. 3, 58). Blagosiljajte svi anđeli Go.spodnji Gospodina, pjesmu recite i uzvisujte. ga u vijeke.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"f1d76cdf3320b82d":{"t":"<i>Pomolimo se</i>.\nUdostoj se, Gospodine, poslati nam za pomoćnika svetoga Rafaela arkanđela, i neka ti on, za koga vjerujemo da uvijek stoji uz tvoje veličanstvo, prinese naše skromne molitve, da ih blagosloviš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dostoj se. Gospodine Bože, upraviti svetog arkanđela svoga Rafaela na našu pomoć, te onaj, za kojega vjerujemo, da je uvijek uz Tvoje veličanstvo, naše neznatne molitve Tebi prinese, da ih blagosloviš, po G. n.","knRef":"Kniewald 1942, str. 746–747 (snimka 374) (OCR)"}}});
